import Pyro4


class PyroProxy(object):
    _MAX_TIMEOUT_SECONDS = 600

    def __init__(self, url, timeout=None):
        self._url = url
        self._timeout = timeout if timeout else self._MAX_TIMEOUT_SECONDS
        self._pyro_client = Pyro4.Proxy(self._url)
        self._pyro_client._Proxy__pyroSetTimeout(self._timeout)

    @property
    def raw_proxy(self):
        return self._pyro_client

    def run_shell_command(self, command):
        return self._pyro_client.run_shell_command(command)

    def get_server_pid(self):
        return self._pyro_client.get_server_pid()
